import { DatePipe } from '@angular/common';
import { Component, Input, SimpleChanges } from '@angular/core';
import { UtilsService } from '../../services/utils.service';
import { TitlecasePipe } from '../../pipes/titlecase.pipe';
import { RouterLink } from '@angular/router';
import { FormsModule } from '@angular/forms';

@Component({
    selector: 'tabla-local',
    imports: [
    TitlecasePipe,
    RouterLink,
    FormsModule
],
    templateUrl: './tabla-local.component.html',
    providers: [DatePipe],
    styleUrl: './tabla-local.component.css'
})
export class TablaLocalComponent {
  @Input() title?:string
  @Input() caption?:string
  @Input() dataSource:any[]=[]
  @Input() keys:string[]=[]
  @Input() ignore:string[]=[]
  @Input() sm?:boolean=false
  @Input() tableClass='table'
  @Input() viewRoute?:string
  @Input() ignoreNumber?:boolean=true
  @Input() urlRoute?:string
  @Input() id:string='id'

  @Input() expand:boolean=false

  filtros:any={}
  lastSort:string=''
  showSearch:boolean=false

  constructor(
    private utils:UtilsService,
    private datePipe: DatePipe,
  ){}

  ngOnChanges(changes:SimpleChanges){
    if(changes['dataSource'] && this.dataSource.length>0){
      this.keys = this.utils.keysOf(this.dataSource[0])
      if(this.ignore.length>0){
        this.keys= this.keys.filter(key => !this.ignore.includes(key))
      }
      this.keys=this.keys.filter( key => typeof this.dataSource[0][key] !=='object')
      if(this.ignoreNumber){
        this.keys= this.keys
        .filter((key)=>
          !this.dataSource.some(row => (typeof row[key]==='number' && key!=='id'))
        )
      }
    }
  }

  filtrar() {
    if (!this.dataSource || this.dataSource.length === 0) return;
  
    const keys = Object.keys(this.filtros).filter((key) => this.filtros[key]); // Filtra claves con valores en los filtros.
  
    if (keys.length === 0) {
      this.dataSource.forEach((row) => row.hidden = false); // Si no hay filtros, muestra todos los elementos.
      return;
    }
  
    this.dataSource.forEach((row) => {
      row.hidden = !keys.every((key) => {
        const rowValue = row[key]?.toString().toLowerCase() || '';
        const filterValue = this.filtros[key]?.toString().toLowerCase() || '';
        return rowValue.includes(filterValue);
      });
    });
  }

  sortByKey(key: string): void {
    const ascending= key===this.lastSort
    this.dataSource.sort((a, b) => {
        const valueA = a[key];
        const valueB = b[key];

        // Compara cadenas de texto o números según el tipo de los valores
        if (valueA < valueB) {
            return ascending ? -1 : 1;
        }
        if (valueA > valueB) {
            return ascending ? 1 : -1;
        }
        return 0; // Si son iguales
    });

    this.lastSort=key
}

  valueClean(value:any):string{
    if(value===null || value===undefined || value===''){
      return 'N/A'
    }
    if(this.utils.isISODateString(value)){
      return this.datePipe.transform(value)??'N/A'
    }
    if(typeof value =='string'){
      return value.toUpperCase()
    }
    return value
  }
}
